// Your partner's name, filled in when the template is added.
const PARTNER = {{partner}};
const INK = '#121A2E';
const SKY = { light: '#dceafd', dark: '#293f6a' };
const WORDS = { light: INK, dark: '#e6f0ff' };
const YOU = { light: '#FFFFFF', dark: '#d6e6ff' };
const THEM = '#FFC2CE';
// Five faces from low to high: each mouth, and eyes open, sleepy or happy.
const FACES = [
  { mouth: 'M8 17 q4 -4 8 0', eyes: 'open' },
  { mouth: 'M8 16 h8', eyes: 'sleepy' },
  { mouth: 'M8 15.5 q4 2 8 0', eyes: 'open' },
  { mouth: 'M7.5 14.5 q4.5 4.5 9 0', eyes: 'open' },
  { mouth: 'M7 14 q5 6 10 0 z', eyes: 'happy' },
];
const MOODS = ['low', 'tired', 'okay', 'good', 'great'];
const EYES = {
  open: 'M7.2 10.3a1.4 1.4 0 1 0 2.8 0a1.4 1.4 0 1 0 -2.8 0z M14 10.3a1.4 1.4 0 1 0 2.8 0a1.4 1.4 0 1 0 -2.8 0z',
  sleepy: 'M7 10.5 h3M14 10.5 h3',
  happy: 'M7 11 q1.5 -2 3 0M14 11 q1.5 -2 3 0',
};

// A face's fill sits in the backdrop and its ink in the tree. In full color they read as one face; tinted and
// clear mode remove the backdrop, and the face stays a line drawing in one color.
function face(index, fill, u, ghost, faint) {
  const size = 56 * u;
  const f = FACES[index];
  const ink = (d, paint) => Object.assign({ type: 'path', d, viewBox: [0, 0, 24, 24] }, paint);
  const line = { color: INK, width: 1.8 * size / 24, cap: 'round' };
  if (ghost) {
    return { type: 'zstack', frame: { width: size, height: size }, children: [
      !faint && { type: 'circle', fill, padding: 1.4 * size / 24 } ] };
  }
  return { type: 'zstack', frame: { width: size, height: size }, opacity: faint ? 0.35 : 1, children: [
    ink('M1.4 12a10.6 10.6 0 1 0 21.2 0a10.6 10.6 0 1 0 -21.2 0z',
      { stroke: { color: INK, width: 1.6 * size / 24, dash: faint ? [3 * u, 2.4 * u] : null } }),
    f.eyes === 'open' ? ink(EYES.open, { fill: INK }) : ink(EYES[f.eyes], { stroke: line }),
    ink(f.mouth, f.mouth.endsWith('z') ? { fill: INK, stroke: line } : { stroke: line }),
  ] };
}

// Both faces and their names, placed by position so the backdrop's fills line up with the tree's ink.
function faces(d, u, width, ghost) {
  const gap = 26 * u;
  const left = 16 * u;
  const right = Math.min(width - 16 * u - 56 * u, left + 56 * u + gap);
  const mine = d.mine ? d.mine.mood : null;
  const next = mine === null ? 2 : (mine + 1) % FACES.length;
  const at = (x, child) => ({ type: 'zstack', padding: { top: 45 * u, leading: x },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' }, children: [child] });
  const label = (x, value) => ({ type: 'zstack', padding: { top: 104.5 * u, leading: x - 12 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' }, children: [
      { type: 'text', value, size: 12 * u, weight: 'bold', color: WORDS, lineLimit: 1, minScale: 0.4,
        frame: { width: 80 * u, height: 16 * u } } ] });
  const you = face(mine === null ? 2 : mine, YOU, u, ghost, mine === null);
  const them = face(d.theirs ? d.theirs.mood : 2, THEM, u, ghost, !d.theirs);
  return [
    at(left, ghost ? you : { type: 'button', action: 'mood' + next,
      label: 'Your mood, ' + (mine === null ? 'not set' : MOODS[mine]), children: [you] }),
    at(right, them),
    !ghost && label(left, 'you'),
    !ghost && label(right, PARTNER),
  ];
}

function render(ctx) {
  // Sizes are in units of `u`, 1/170 of the widget's height.
  const u = ctx.height / 170;
  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: SKY,
      children: faces(ctx.data, u, ctx.width, true) },
    children: [
      { type: 'text', value: 'Our moods', size: 13 * u, weight: 'bold', color: WORDS, lineLimit: 1,
        padding: { top: 15 * u, leading: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' } },
      faces(ctx.data, u, ctx.width, false),
    ],
  };
}
